package org.marketreview.nativeapp;
import android.content.Context;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
final class MigrationStatusScreen extends LinearLayout {
 interface Snapshot{JSONObject current()throws Exception;}
 interface Available{boolean test(String entryId,String route)throws Exception;}
 interface Open{void open(String entryId,String route)throws Exception;}
 interface Evidence{JSONObject read(String entryId,String reference)throws Exception;}
 interface Work{void run()throws Exception;}
 final Snapshot provider;final Available available;final Open opener;final Evidence evidence;final FrameLayout container;final ScrollView main;final LinearLayout detailPage,proofPage,rows;final TextView header,count,state,detail,proof;final EditText search;final Map<String,Spinner> filters=new LinkedHashMap<>();final Map<String,String> selectedFilters=new LinkedHashMap<>();final Map<String,List<String>> values=new LinkedHashMap<>();final Spinner refs;final Button previous,next,jump,readEvidence;final ScrollView detailScroll,proofScroll;JSONObject snapshot=new JSONObject(),entry=new JSONObject(),response=new JSONObject();JSONArray matches=new JSONArray();int page=0,view=0;boolean restoring=false,dark;String entryVersion="未知",entryAsOf="未知";SourceHandoffPanel.Exporter exporter;
 MigrationStatusScreen(Context c,Snapshot provider,Available available,Open opener,Evidence evidence){super(c);setOrientation(VERTICAL);this.provider=provider;this.available=available;this.opener=opener;this.evidence=evidence;container=new FrameLayout(c);addView(container,new LayoutParams(-1,-1));main=new ScrollView(c);LinearLayout body=new LinearLayout(c);body.setOrientation(VERTICAL);main.addView(body);header=new TextView(c);header.setText("迁移状态 · 尚无有效冻结快照");body.addView(header);search=new EditText(c);search.setHint("搜索标题、缺口或完整证据记录");body.addView(search);String[] keys={"platform","module","implementation","acceptance","externalBlocker"},labels={"平台","模块","实现","验收","外部阻断"};for(int i=0;i<keys.length;i++){String key=keys[i];TextView label=new TextView(c);label.setText(labels[i]);body.addView(label);Spinner spinner=new Spinner(c);filters.put(key,spinner);values.put(key,new ArrayList<>());selectedFilters.put(key,"");body.addView(spinner);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int index,long id){if(!restoring&&index==spinner.getSelectedItemPosition()){List<String> choices=values.get(key);if(index>=0&&index<choices.size()&&!choices.get(index).equals(selectedFilters.get(key))){selectedFilters.put(key,choices.get(index));page=0;guard(()->render());}}}});}count=new TextView(c);body.addView(count);rows=new LinearLayout(c);rows.setOrientation(VERTICAL);body.addView(rows);LinearLayout paging=new LinearLayout(c);previous=new Button(c);previous.setText("上一页");next=new Button(c);next.setText("下一页");paging.addView(previous,new LayoutParams(0,-2,1));paging.addView(next,new LayoutParams(0,-2,1));body.addView(paging);state=new TextView(c);addView(state);container.setLayoutParams(new LayoutParams(-1,0,1));button(body,"重新读取注入快照",()->refresh());button(body,"导出完整当前快照",()->{MigrationStatusModel.require(snapshot.length()>0&&exporter!=null,"尚无有效快照或宿主未接导出");exporter.write("migration-status.json","application/json",MigrationStatusModel.json(snapshot).getBytes(StandardCharsets.UTF_8));state.setText("已交给文件选择；实际写入结果由宿主确认。导出包含全部审查项。");});
 detailPage=new LinearLayout(c);detailPage.setOrientation(VERTICAL);button(detailPage,"返回筛选列表",()->show(0));detailScroll=new ScrollView(c);detail=new TextView(c);detail.setTextIsSelectable(true);detailScroll.addView(detail);detailPage.addView(detailScroll,new LayoutParams(-1,0,1));jump=new Button(c);detailPage.addView(jump);refs=new Spinner(c);detailPage.addView(refs);readEvidence=new Button(c);readEvidence.setText("读取所选证据");detailPage.addView(readEvidence);proofPage=new LinearLayout(c);proofPage.setOrientation(VERTICAL);button(proofPage,"返回完整审查项",()->show(1));proofScroll=new ScrollView(c);proof=new TextView(c);proof.setTextIsSelectable(true);proofScroll.addView(proof);proofPage.addView(proofScroll,new LayoutParams(-1,0,1));
 previous.setOnClickListener(v->guard(()->{if(page>0){page--;render();}}));next.setOnClickListener(v->guard(()->{if((page+1)*20<matches.length()){page++;render();}}));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int d){if(!restoring){page=0;guard(()->render());}}});jump.setOnClickListener(v->guard(()->{fresh();MigrationStatusModel.require(opener!=null&&available!=null&&available.test(entry.getString("id"),entry.optString("route")),"入口当前未接入；未执行跳转");opener.open(entry.getString("id"),entry.optString("route"));}));readEvidence.setOnClickListener(v->guard(()->{fresh();MigrationStatusModel.require(evidence!=null&&refs.getSelectedItem()!=null,"没有可解析的证据引用");JSONObject captured=evidence.read(entry.getString("id"),refs.getSelectedItem().toString());MigrationStatusModel.json(captured);response=new JSONObject(MigrationStatusModel.json(captured));proof.setText(MigrationStatusModel.proof(response));show(2);}));show(0);refresh();}
 void guard(Work w){try{w.run();}catch(Exception e){state.setText(e.getMessage());android.widget.Toast.makeText(getContext(),e.getMessage(),android.widget.Toast.LENGTH_SHORT).show();}}
 void button(LinearLayout parent,String title,Work work){Button b=new Button(getContext());b.setText(title);parent.addView(b);b.setOnClickListener(v->guard(work));}
 JSONObject query()throws Exception{JSONObject q=new JSONObject().put("search",search.getText().toString());for(String key:filters.keySet()){int index=filters.get(key).getSelectedItemPosition();List<String> list=values.get(key);q.put(key,selectedFilters.get(key));}return q;}
 void refresh(){guard(()->{MigrationStatusModel.require(provider!=null,"宿主尚未提供迁移快照");JSONObject candidate=MigrationStatusModel.validate(provider.current()),old=query();snapshot=new JSONObject(MigrationStatusModel.json(candidate));restoring=true;for(String key:filters.keySet()){List<String> list=values.get(key);list.clear();list.add("");list.addAll(MigrationStatusModel.options(snapshot,key));List<String> labels=new ArrayList<>(list);labels.set(0,"全部");filters.get(key).setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels));int index=list.indexOf(old.optString(key));selectedFilters.put(key,index<0?"":list.get(index));filters.get(key).setSelection(index<0?0:index);}restoring=false;header.setText(MigrationStatusModel.summary(snapshot));render();state.setText("仅显示宿主注入的冻结快照；没有更新项目状态");});}
 void render()throws Exception{if(snapshot.length()==0)return;matches=MigrationStatusModel.filter(snapshot,query());page=Math.max(0,Math.min(page,Math.max(0,(matches.length()-1)/20)));rows.removeAllViews();for(int i=page*20;i<Math.min(matches.length(),(page+1)*20);i++){JSONObject r=matches.getJSONObject(i);button(rows,MigrationStatusModel.field(r,"id")+" · "+MigrationStatusModel.field(r,"title")+" · "+MigrationStatusModel.field(r,"nativeStatus"),()->{entry=new JSONObject(MigrationStatusModel.json(r));entryVersion=MigrationStatusModel.field(snapshot,"version");entryAsOf=MigrationStatusModel.field(snapshot,"asOf");showDetail();});}count.setText("匹配 "+matches.length()+" / 全量 "+snapshot.getJSONArray("entries").length()+" · 第 "+(page+1)+"/"+Math.max(1,(matches.length()+19)/20)+" 页 · 每页20项");previous.setEnabled(page>0);next.setEnabled((page+1)*20<matches.length());SourceHandoffPanel.styleTree(rows,dark);}
 void showDetail()throws Exception{detail.setText("所读冻结版本："+entryVersion+" / "+entryAsOf+"\n"+MigrationStatusModel.detail(entry));List<String> list=MigrationStatusModel.references(entry);refs.setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_dropdown_item,list));boolean enabled=available!=null&&opener!=null&&available.test(entry.getString("id"),entry.optString("route"));jump.setEnabled(enabled);jump.setText(enabled?"打开已接入原生功能":"原生入口未接入（禁用，不代表完成）");readEvidence.setEnabled(evidence!=null&&!list.isEmpty());show(1);}
 void fresh()throws Exception{MigrationStatusModel.require(provider!=null,"当前快照不可核验");JSONObject current=MigrationStatusModel.validate(provider.current());JSONArray all=current.getJSONArray("entries");for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(r.optString("id").equals(entry.optString("id"))){MigrationStatusModel.require(SourceAnalysisPacket.canonical(r).equals(SourceAnalysisPacket.canonical(entry)),"审查项已变化；请返回并重新读取快照");return;}}throw new IllegalArgumentException("当前快照已缺少该审查项");}
 void show(int index){view=index;container.removeAllViews();container.addView(index==0?main:index==1?detailPage:proofPage,new FrameLayout.LayoutParams(-1,-1));SourceHandoffPanel.styleTree(container,dark);}
 boolean back(){if(view==0)return false;show(view-1);return true;}
 void setFileActions(SourceHandoffPanel.Exporter exporter){this.exporter=exporter;}
 void setDarkTheme(boolean dark){this.dark=dark;SourceHandoffPanel.styleTree(this,dark);}
 JSONObject saveState()throws Exception{JSONObject saved=new JSONObject().put("filters",query()).put("page",page).put("view",view).put("entry",entry).put("entryVersion",entryVersion).put("entryAsOf",entryAsOf).put("response",response).put("listScroll",main.getScrollY()).put("detailScroll",detailScroll.getScrollY()).put("evidenceScroll",proofScroll.getScrollY()).put("evidenceReference",refs.getSelectedItem()==null?"":refs.getSelectedItem().toString());return new JSONObject(MigrationStatusModel.json(saved));}
 void restoreState(JSONObject input)throws Exception{JSONObject s=new JSONObject(MigrationStatusModel.json(input));JSONObject q=s.optJSONObject("filters");if(q==null)q=new JSONObject();restoring=true;search.setText(q.optString("search"));for(String key:filters.keySet()){int index=values.get(key).indexOf(q.optString(key));selectedFilters.put(key,index<0?"":values.get(key).get(index));filters.get(key).setSelection(index<0?0:index);}restoring=false;page=Math.max(0,s.optInt("page"));render();entry=s.optJSONObject("entry");if(entry==null)entry=new JSONObject();response=s.optJSONObject("response");if(response==null)response=new JSONObject();entryVersion=MigrationStatusModel.field(s,"entryVersion");entryAsOf=MigrationStatusModel.field(s,"entryAsOf");int index=s.optInt("view");if(index>0&&entry.length()>0){showDetail();List<String> references=MigrationStatusModel.references(entry);int selected=references.indexOf(s.optString("evidenceReference"));if(selected>=0)refs.setSelection(selected);if(index==2){proof.setText(MigrationStatusModel.proof(response));show(2);}}else show(0);main.post(()->main.scrollTo(0,s.optInt("listScroll")));detailScroll.post(()->detailScroll.scrollTo(0,s.optInt("detailScroll")));proofScroll.post(()->proofScroll.scrollTo(0,s.optInt("evidenceScroll")));}
}




